def solve(grid):
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    rows = len(grid)
    cols = len(grid[0])

    # Find all 2x2 blocks (top-left corner, color)
    blocks = []
    for r in range(rows - 1):
        for c in range(cols - 1):
            val = grid[r][c]
            if val != 0 and grid[r][c+1] == val and grid[r+1][c] == val and grid[r+1][c+1] == val:
                blocks.append((r, c, val))

    # Initialize output as copy of input
    output = [row[:] for row in grid]

    # Horizontal connections: group by row and color
    row_groups = {}
    for r, c, val in blocks:
        key = (r, val)
        if key not in row_groups:
            row_groups[key] = []
        row_groups[key].append(c)

    for (r, val), c_list in row_groups.items():
        c_list.sort()
        for i in range(len(c_list) - 1):
            c1 = c_list[i]
            c2 = c_list[i+1]
            # Fill gap between the two blocks with 5s
            for c in range(c1 + 2, c2):
                output[r][c] = 5
                output[r+1][c] = 5

    # Vertical connections: group by column and color
    col_groups = {}
    for r, c, val in blocks:
        key = (c, val)
        if key not in col_groups:
            col_groups[key] = []
        col_groups[key].append(r)

    for (c, val), r_list in col_groups.items():
        r_list.sort()
        for i in range(len(r_list) - 1):
            r1 = r_list[i]
            r2 = r_list[i+1]
            gap_size = r2 - r1 - 2
            # Only fill vertical gaps of size <= 4
            if gap_size <= 4:
                for r in range(r1 + 2, r2):
                    output[r][c] = 5
                    output[r][c+1] = 5

    return output
